// src/lib/mcp/tools/search-faqs.ts
import { defineTool as defineTool5 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z2 } from "npm:zod@^3.25.76";
var SITE5 = "https://orthoautomate.online";
var allFaqs = () => {
  const fromServices = services.flatMap(
    (s) => s.faqs.map((f) => ({
      question: f.q,
      answer: f.a,
      source: s.shortName,
      url: `${SITE5}/services/${s.slug}`
    }))
  );
  const fromLanding = landingPages.flatMap(
    (p) => p.faqs.map((f) => ({
      question: f.q,
      answer: f.a,
      source: p.breadcrumbLabel,
      url: `${SITE5}/${p.slug}`
    }))
  );
  return [...fromServices, ...fromLanding];
};
var search_faqs_default = defineTool5({
  name: "search_faqs",
  title: "Search FAQs",
  description: "Search OrthoAutomate's published FAQ answers about pricing, setup time, integrations, HIPAA/compliance, AI call handling and results. Omit the query to get every FAQ.",
  inputSchema: {
    query: z2.string().describe("Keywords to match against questions and answers. Use an empty string for all FAQs."),
    limit: z2.number().int().min(1).max(50).describe("Maximum number of FAQs to return.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query, limit }) => {
    const q = query.trim().toLowerCase();
    const terms = q.split(/\s+/).filter(Boolean);
    const scored = allFaqs().map((f) => {
      const haystack = `${f.question} ${f.answer}`.toLowerCase();
      const score = terms.length ? terms.reduce((acc, t) => acc + (haystack.includes(t) ? 1 : 0), 0) : 1;
      return { ...f, score };
    }).filter((f) => f.score > 0).sort((a, b) => b.score - a.score).slice(0, limit).map(({ score: _score, ...rest }) => rest);
    return {
      content: [{ type: "text", text: JSON.stringify(scored, null, 2) }],
      structuredContent: { faqs: scored, count: scored.length }
    };
  }
});

