// src/lib/mcp/tools/list-articles.ts
var SITE7 = "https://orthoautomate.online";
var list_articles_default = defineTool7({
  name: "list_articles",
  title: "List blog articles",
  description: "List OrthoAutomate blog articles with slug, title, one-sentence summary, author, publish/update dates and tags. Use get_article to read the full text.",
  inputSchema: {},
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: () => {
    const items = articles.map((a) => ({
      slug: a.slug,
      title: a.title,
      summary: a.summary,
      author: a.author,
      publishedAt: a.publishedAt,
      updatedAt: a.updatedAt,
      readingMinutes: a.readingMinutes,
      tags: a.tags,
      url: `${SITE7}/blog/${a.slug}`
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(items, null, 2) }],
      structuredContent: { articles: items }
    };
  }
});

// src/lib/mcp/tools/get-article.ts
import { defineTool as defineTool8 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z3 } from "npm:zod@^3.25.76";
var SITE8 = "https://orthoautomate.online";
var get_article_default = defineTool8({
  name: "get_article",
  title: "Get blog article",
  description: "Read the full text of one OrthoAutomate blog article as markdown, including all sections and subsections. Use list_articles to find the slug.",
  inputSchema: {
    slug: z3.string().min(1).describe("Article slug from list_articles.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ slug }) => {
    const article = articles.find((a) => a.slug === slug.trim().toLowerCase());
    if (!article) {
      return {
        content: [
          {
            type: "text",
            text: `No article found for slug "${slug}". Available slugs: ${articles.map((a) => a.slug).join(", ")}.`
          }
        ],
        isError: true
      };
    }
    const lines = [
      `# ${article.title}`,
      "",
      `By ${article.author} \u2014 published ${article.publishedAt}, updated ${article.updatedAt}`,
      "",
      article.intro,
      ""
    ];
    for (const section of article.sections) {
      lines.push(`## ${section.heading}`, "");
      for (const p of section.paragraphs ?? []) lines.push(p, "");
      for (const b of section.bullets ?? []) lines.push(`- ${b}`);
      if (section.bullets?.length) lines.push("");
      for (const sub of section.subsections ?? []) {
        lines.push(`### ${sub.heading}`, "");
        for (const p of sub.paragraphs) lines.push(p, "");
      }
    }
    const markdown = lines.join("\n").trim();
    const url = `${SITE8}/blog/${article.slug}`;
    return {
      content: [{ type: "text", text: `${markdown}

Source: ${url}` }],
      structuredContent: { slug: article.slug, title: article.title, url, markdown }
    };
  }
});

